<?php
require_once '../config/database.php';require_once '../includes/auth.php';require_role('student');$page_title='Личный кабинет';
$q=$pdo->prepare("SELECT st.id,st.group_id,CONCAT(st.surname,' ',st.name) full_name,g.name group_name FROM students st JOIN groups g ON g.id=st.group_id WHERE st.user_id=?");$q->execute([$_SESSION['user']['id']]);$st=$q->fetch();$sid=(int)($st['id']??0);$gid=(int)($st['group_id']??0);
$q=$pdo->prepare('SELECT ROUND(AVG(grade),2) FROM grades WHERE student_id=?');$q->execute([$sid]);$avg=$q->fetchColumn();$q=$pdo->prepare("SELECT COALESCE(ROUND(100*SUM(status IN ('PRESENT','LATE'))/NULLIF(COUNT(*),0),1),0) FROM attendance WHERE student_id=?");$q->execute([$sid]);$attendance=(float)$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM attendance WHERE student_id=? AND status='ABSENT'");$q->execute([$sid]);$missed=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT l.*,s.name subject_name FROM lessons l JOIN subjects s ON s.id=l.subject_id WHERE l.group_id=? AND (l.lesson_date>CURDATE() OR (l.lesson_date=CURDATE() AND l.end_time>=CURTIME())) ORDER BY l.lesson_date,l.start_time LIMIT 4");$q->execute([$gid]);$next=$q->fetchAll();$q=$pdo->prepare("SELECT gr.grade,gr.grade_date,s.name subject_name FROM grades gr JOIN subjects s ON s.id=gr.subject_id WHERE gr.student_id=? ORDER BY gr.grade_date DESC,gr.id DESC LIMIT 5");$q->execute([$sid]);$recentGrades=$q->fetchAll();include '../includes/header.php';?>
<div class="notice info">Здравствуйте, <b><?=htmlspecialchars($st['full_name']??$_SESSION['user']['login'])?></b>! Группа: <?=htmlspecialchars($st['group_name']??'—')?>.</div>
<div class="cards"><div class="card"><div class="kpi-icon">⭐</div><div class="label">Средний балл</div><div class="value"><?=$avg?:'—'?></div></div><div class="card"><div class="kpi-icon">✅</div><div class="label">Посещаемость</div><div class="value"><?=$attendance?>%</div></div><div class="card"><div class="kpi-icon">❌</div><div class="label">Пропусков</div><div class="value"><?=$missed?></div></div><div class="card"><div class="kpi-icon">📅</div><div class="label">Ближайших занятий</div><div class="value"><?=count($next)?></div></div></div>
<div class="dashboard-grid"><div class="panel"><div class="section-head"><h2>Ближайшее расписание</h2><a class="btn secondary" href="schedule.php">Полное расписание</a></div><?php if($next):?><div class="schedule-list"><?php foreach($next as $r):?><div class="schedule-item <?=$r['lesson_date']===date('Y-m-d')?'today-mark':''?>"><div><b><?=date('d.m',strtotime($r['lesson_date']))?></b></div><div><b><?=htmlspecialchars($r['subject_name'])?></b><br><small><?=htmlspecialchars($r['lesson_type'])?> · ауд. <?=htmlspecialchars($r['classroom'])?></small></div><div class="schedule-time"><?=substr($r['start_time'],0,5)?></div></div><?php endforeach;?></div><?php else:?><div class="empty-state">Ближайших занятий нет.</div><?php endif;?></div><div class="panel"><div class="section-head"><h2>Последние оценки</h2><a class="btn secondary" href="grades.php">Все оценки</a></div><?php if($recentGrades):?><div class="table-wrap"><table><tr><th>Предмет</th><th>Дата</th><th>Оценка</th></tr><?php foreach($recentGrades as $r):?><tr><td><?=htmlspecialchars($r['subject_name'])?></td><td><?=date('d.m',strtotime($r['grade_date']))?></td><td><span class="grade grade-<?=$r['grade']?>"><?=$r['grade']?></span></td></tr><?php endforeach;?></table></div><?php else:?><div class="empty-state">Оценок пока нет.</div><?php endif;?></div></div>
<?php include '../includes/footer.php';?>
